// @zeus-internal
import {
  fibonacciPoint,
  rotatePoint,
  spherePoint,
  type SectionPoint,
} from "./section-math";
// Hand-authored coarse geographic silhouettes; these are illustrative, not cartographic data.
const regions = [
  [
    [-168, 70],
    [-120, 73],
    [-65, 50],
    [-82, 8],
    [-110, 20],
    [-130, 48],
  ],
  [
    [-80, 12],
    [-35, -5],
    [-50, -35],
    [-70, -56],
    [-82, -5],
  ],
  [
    [-18, 35],
    [10, 38],
    [45, 12],
    [35, -25],
    [16, -36],
    [-10, 5],
  ],
  [
    [-10, 36],
    [-10, 62],
    [30, 72],
    [85, 73],
    [170, 58],
    [140, 33],
    [115, 0],
    [80, 5],
    [45, 32],
  ],
  [
    [112, -11],
    [155, -10],
    [153, -40],
    [115, -36],
  ],
  [
    [-57, 60],
    [-20, 65],
    [-40, 84],
    [-62, 78],
  ],
];
function contains(lon: number, lat: number, polygon: number[][]) {
  let inside = false;
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const a = polygon[i],
      b = polygon[j];
    if (
      a[1] > lat !== b[1] > lat &&
      lon < ((b[0] - a[0]) * (lat - a[1])) / (b[1] - a[1]) + a[0]
    )
      inside = !inside;
  }
  return inside;
}
export const sectionLandDots = Array.from({ length: 2400 }, (_, i) =>
  fibonacciPoint(i, 2400),
).filter(([x, y, z]) => {
  const lat = (-Math.asin(y) * 180) / Math.PI,
    lon = (Math.atan2(x, z) * 180) / Math.PI;
  return regions.some((region) => contains(lon, lat, region));
});
export function sphereRoute(
  from: SectionPoint,
  to: SectionPoint,
  yaw: number,
  pitch: number,
  radius: number,
  cx: number,
  cy: number,
) {
  const dot = Math.max(
      -0.9999,
      Math.min(
        0.9999,
        from.reduce((sum, n, i) => sum + n * to[i], 0),
      ),
    ),
    angle = Math.acos(dot);
  let path = "",
    pen = false;
  for (let i = 0; i <= 40; i++) {
    const t = i / 40,
      a = Math.sin((1 - t) * angle) / Math.sin(angle),
      b = Math.sin(t * angle) / Math.sin(angle),
      lift = 1 + 0.19 * Math.sin(t * Math.PI);
    const p = rotatePoint(
      [
        (from[0] * a + to[0] * b) * lift,
        (from[1] * a + to[1] * b) * lift,
        (from[2] * a + to[2] * b) * lift,
      ],
      yaw,
      pitch,
    );
    if (p[2] < 0) {
      pen = false;
      continue;
    }
    path += `${pen ? "L" : "M"}${(cx + p[0] * radius).toFixed(2)},${(cy + p[1] * radius).toFixed(2)} `;
    pen = true;
  }
  return path;
}
export { spherePoint };

"use client";
import { useEffect, type CSSProperties, type ReactNode } from "react";
import { motion } from "motion/react";
import { rotatePoint } from "./section-math";
import { sectionLandDots, spherePoint, sphereRoute } from "./globe-geometry";
import {
  sectionStyles,
  useSectionEnvironment,
  useSectionSelection,
  useSphereRotation,
} from "./section-shared";
export interface NetworkGlobeStore {
  id: string;
  name: string;
  latitude: number;
  longitude: number;
  description?: ReactNode;
}
export interface NetworkGlobeProps {
  stores: readonly NetworkGlobeStore[];
  title?: ReactNode;
  description?: ReactNode;
  index?: number;
  defaultIndex?: number;
  onChange?: (index: number) => void;
  onSelect?: (store: NetworkGlobeStore) => void;
  drag?: boolean;
  autoplay?: boolean;
  speed?: number;
  dotColor?: string;
  routeColor?: string;
  height?: number;
  className?: string;
  style?: CSSProperties;
  label?: string;
}
/** Draggable geographic sphere with destination targeting and raised great-circle routes. */
export function NetworkGlobe({
  stores,
  title = "Across the map",
  description,
  index,
  defaultIndex = 0,
  onChange,
  onSelect,
  drag = true,
  autoplay = true,
  speed = 0.035,
  dotColor = "#b44816",
  routeColor = "#eee9dc",
  height = 720,
  className = "",
  style,
  label = "Store network",
}: NetworkGlobeProps) {
  const env = useSectionEnvironment(),
    selection = useSectionSelection(
      stores.length,
      index,
      defaultIndex,
      onChange,
    ),
    sphere = useSphereRotation(env.active, env.reduced, autoplay, speed, drag),
    selected = stores[selection.selected],
    yaw = sphere.rotation.yaw,
    pitch = sphere.rotation.pitch;
  useEffect(() => {
    if (selected)
      sphere.orient(
        (-selected.longitude * Math.PI) / 180,
        (-selected.latitude * Math.PI) / 180,
      );
  }, [selected?.id, selected?.longitude, selected?.latitude, sphere.orient]);
  const locations = stores.map((store, i) => {
    const [x, y, z] = rotatePoint(
      spherePoint(store.latitude, store.longitude),
      yaw,
      pitch,
    );
    return {
      store,
      i,
      x: 320 + x * 210,
      y: 260 + y * 210,
      z,
      width: store.name.length * 6.5 + 18,
      offset: 0,
    };
  });
  const placed: { x: number; y: number; width: number }[] = [];
  // Keep the selected label readable, then move crowded labels along short leader lines.
  for (const location of [...locations].sort(
    (a, b) =>
      Number(b.i === selection.selected) - Number(a.i === selection.selected),
  )) {
    if (location.z <= 0) continue;
    let attempts = 0;
    while (
      attempts++ < 12 &&
      placed.some(
        (other) =>
          Math.abs(other.x - location.x) <
            (other.width + location.width) / 2 + 4 &&
          Math.abs(other.y - (location.y + location.offset)) < 27,
      )
    )
      location.offset -= 28;
    placed.push({
      x: location.x,
      y: location.y + location.offset,
      width: location.width,
    });
  }
  const select = (i: number) => {
    selection.select(i);
    if (stores[i]) onSelect?.(stores[i]);
  };
  return (
    <div
      ref={env.ref}
      role="region"
      aria-label={label}
      tabIndex={0}
      className={`z-as z-as-network ${className}`}
      data-section="network-globe"
      data-index={selection.selected}
      data-yaw={yaw.toFixed(5)}
      data-pitch={pitch.toFixed(5)}
      {...sphere.handlers}
      onKeyDown={(event) => {
        if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
          event.preventDefault();
          selection.select(
            selection.current.current + (event.key === "ArrowRight" ? 1 : -1),
          );
        }
      }}
      style={{ height: `min(${height}px,100svh)`, minHeight: 520, ...style }}
    >
      <style>
        {sectionStyles +
          `.z-as-network{overflow:hidden;background:#101010;color:#e8e5df;touch-action:pan-y;user-select:none}.z-as-network h2{position:absolute;top:30px;left:3.2%;right:3.2%;font-size:clamp(30px,4vw,48px);line-height:1.1;font-weight:400;letter-spacing:-.04em;pointer-events:none}.z-as-network .z-as-network-globe{position:absolute;top:78px;left:0;width:100%;height:calc(100% - 195px);overflow:visible;cursor:grab}.z-as-network .z-as-network-bottom{position:absolute;bottom:30px;left:3.2%;right:3.2%;display:grid;grid-template-columns:1fr auto 1fr;gap:22px;align-items:end}.z-as-network .z-as-network-bottom>small{font-size:12px;color:#888}.z-as-network .z-as-network-description{font-size:13px;max-width:310px;justify-self:end;color:#aaa}.z-as-network .z-as-location{cursor:pointer}.z-as-network .z-as-location:focus-visible{outline:none}.z-as-network .z-as-location:focus-visible rect{stroke:#548bff;stroke-width:3}@media(max-width:600px){.z-as-network .z-as-network-globe{top:100px;height:calc(100% - 255px)}.z-as-network .z-as-network-bottom{grid-template-columns:1fr auto;bottom:22px}.z-as-network .z-as-network-description{grid-column:1/-1;justify-self:start;max-width:100%;font-size:12px}.z-as-network h2{top:25px}}`}
      </style>
      <h2>{title}</h2>
      <svg
        className="z-as-network-globe"
        viewBox="0 0 640 520"
        aria-label="Draggable dotted globe"
      >
        <circle cx="320" cy="260" r="210" fill="none" stroke="#ffffff0c" />
        {sectionLandDots.map((point, i) => {
          const [x, y, z] = rotatePoint(point, yaw, pitch);
          return z > -0.05 ? (
            <circle
              key={i}
              cx={320 + x * 210}
              cy={260 + y * 210}
              r={1.25}
              fill={dotColor}
              opacity={0.15 + 0.8 * Math.max(0, z)}
            />
          ) : null;
        })}
        {selected &&
          stores.map((store, i) =>
            i !== selection.selected ? (
              <motion.path
                key={`${selected.id}-${store.id}`}
                data-route={store.id}
                d={sphereRoute(
                  spherePoint(selected.latitude, selected.longitude),
                  spherePoint(store.latitude, store.longitude),
                  yaw,
                  pitch,
                  210,
                  320,
                  260,
                )}
                fill="none"
                stroke={routeColor}
                strokeWidth=".8"
                opacity=".38"
                initial={env.reduced ? false : { pathLength: 0 }}
                animate={{ pathLength: 1 }}
                transition={{
                  duration: env.reduced ? 0 : 1.1,
                  delay: env.reduced ? 0 : i * 0.025,
                }}
              />
            ) : null,
          )}
        {locations.map(({ store, i, x, y, z, width, offset }) => {
          return (
            <g
              key={store.id}
              className="z-as-location"
              role="button"
              aria-label={`Select ${store.name}`}
              tabIndex={z > 0 ? 0 : -1}
              data-location={store.id}
              data-depth={z.toFixed(3)}
              aria-hidden={z <= 0}
              transform={`translate(${x},${y})`}
              opacity={z > 0 ? 1 : 0}
              style={{ pointerEvents: z > 0 ? "auto" : "none" }}
              onClick={() => select(i)}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  select(i);
                }
              }}
            >
              <circle r="2.5" fill={routeColor} />
              {offset !== 0 && (
                <path
                  d={`M0,-4 L0,${offset - 8}`}
                  fill="none"
                  stroke={routeColor}
                  opacity=".4"
                  strokeWidth=".7"
                />
              )}
              <rect
                x={-width / 2}
                y={-31 + offset}
                width={width}
                height="23"
                rx="6"
                fill={i === selection.selected ? "#eee9df" : "#2c2927"}
              />
              <text
                y={-15 + offset}
                textAnchor="middle"
                fontSize="11"
                fill={i === selection.selected ? "#171717" : "#eee9df"}
              >
                {store.name}
              </text>
            </g>
          );
        })}
      </svg>
      <div className="z-as-network-bottom">
        <small>{stores.length} locations</small>
        <nav className="z-as-pill" aria-label="Store navigation">
          <button
            type="button"
            aria-label="Previous store"
            onClick={() => selection.select(selection.current.current - 1)}
          >
            ‹
          </button>
          <span aria-live="polite">{selected?.name ?? "No locations"}</span>
          <button
            type="button"
            aria-label="Next store"
            onClick={() => selection.select(selection.current.current + 1)}
          >
            ›
          </button>
        </nav>
        <div className="z-as-network-description">
          {selected?.description ?? description}
        </div>
      </div>
    </div>
  );
}

// @zeus-internal
export const sectionClamp = (value: number, min = 0, max = 1) =>
  Math.min(max, Math.max(min, Number.isFinite(value) ? value : 0));
export const sectionWrap = (value: number, count: number) =>
  count > 0 ? ((value % count) + count) % count : 0;
export type SectionPoint = readonly [number, number, number];
export function spherePoint(latitude: number, longitude: number): SectionPoint {
  const lat = (latitude * Math.PI) / 180,
    lon = (longitude * Math.PI) / 180;
  return [
    Math.cos(lat) * Math.sin(lon),
    -Math.sin(lat),
    Math.cos(lat) * Math.cos(lon),
  ];
}
export function rotatePoint(
  [x, y, z]: SectionPoint,
  yaw: number,
  pitch: number,
): SectionPoint {
  const xx = x * Math.cos(yaw) + z * Math.sin(yaw),
    zz = z * Math.cos(yaw) - x * Math.sin(yaw);
  return [
    xx,
    y * Math.cos(pitch) - zz * Math.sin(pitch),
    zz * Math.cos(pitch) + y * Math.sin(pitch),
  ];
}
export function fibonacciPoint(index: number, count: number): SectionPoint {
  const y = 1 - (2 * (index + 0.5)) / Math.max(1, count),
    r = Math.sqrt(1 - y * y),
    angle = index * Math.PI * (3 - Math.sqrt(5));
  return [Math.cos(angle) * r, y, Math.sin(angle) * r];
}

// @zeus-internal
"use client";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type RefObject,
  type PointerEvent,
} from "react";
import { sectionClamp, sectionWrap } from "./section-math";
export interface SectionInternalMedia {
  src?: string;
  alt?: string;
  content?: ReactNode;
}
export interface SectionInternalItem extends SectionInternalMedia {
  id: string;
  title: string;
  description?: string;
}
export interface SectionInternalBase {
  className?: string;
  style?: CSSProperties;
  height?: number;
  label?: string;
}
export interface SectionInternalLink {
  label: string;
  href: string;
}
export interface SectionInternalGroup {
  title: string;
  links: readonly SectionInternalLink[];
}
export function useSectionEnvironment() {
  const ref = useRef<HTMLDivElement>(null),
    [size, setSize] = useState({ width: 1000, height: 640 }),
    [active, setActive] = useState(false),
    [reduced, setReduced] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    let visible = true;
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => {
      setActive(visible && !document.hidden);
      setReduced(media.matches);
    };
    const resize = () =>
      setSize({
        width: node.clientWidth || 1000,
        height: node.clientHeight || 640,
      });
    const ro =
      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(resize);
    ro?.observe(node);
    const io =
      typeof IntersectionObserver === "undefined"
        ? null
        : new IntersectionObserver((entries) => {
            visible = entries[0]?.isIntersecting ?? true;
            update();
          });
    io?.observe(node);
    media.addEventListener("change", update);
    document.addEventListener("visibilitychange", update);
    resize();
    update();
    return () => {
      ro?.disconnect();
      io?.disconnect();
      media.removeEventListener("change", update);
      document.removeEventListener("visibilitychange", update);
    };
  }, []);
  return { ref, size, active, reduced };
}
export function useSectionLoop(
  active: boolean,
  callback: (delta: number) => void,
) {
  const latest = useRef(callback);
  latest.current = callback;
  useEffect(() => {
    if (!active) return;
    let frame = 0,
      last = 0;
    const tick = (now: number) => {
      const delta = last ? Math.min(0.04, (now - last) / 1000) : 0;
      last = now;
      latest.current(delta);
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [active]);
}
export function useSectionSelection(
  count: number,
  index: number | undefined,
  defaultIndex: number,
  onChange?: (index: number) => void,
) {
  const [local, setLocal] = useState(defaultIndex);
  const selected = sectionWrap(Math.round(index ?? local), count),
    current = useRef(selected);
  current.current = selected;
  const select = useCallback(
    (next: number) => {
      next = sectionWrap(Math.round(next), count);
      if (next === current.current) return;
      if (index === undefined) {
        current.current = next;
        setLocal(next);
      }
      onChange?.(next);
    },
    [count, index, onChange],
  );
  return { selected, select, current };
}
export function useSectionScroll(
  ref: RefObject<HTMLElement | null>,
  scrollContainer?: RefObject<HTMLElement | null>,
  onProgress?: (progress: number) => void,
) {
  const [progress, setProgress] = useState(0),
    latest = useRef(onProgress),
    previous = useRef(-1);
  latest.current = onProgress;
  useLayoutEffect(() => {
    const node = ref.current;
    if (!node) return;
    let frame = 0;
    const container = scrollContainer?.current;
    const measure = () => {
      frame = 0;
      const box = node.getBoundingClientRect(),
        top = container?.getBoundingClientRect().top ?? 0,
        view = container?.clientHeight ?? innerHeight;
      const next = sectionClamp(
        (top - box.top) / Math.max(1, box.height - view),
      );
      if (Math.abs(previous.current - next) >= 0.0001) {
        previous.current = next;
        setProgress(next);
        latest.current?.(next);
      }
    };
    const request = () => {
      if (!frame) frame = requestAnimationFrame(measure);
    };
    const target = container ?? window;
    target.addEventListener("scroll", request, { passive: true });
    window.addEventListener("resize", request);
    const ro =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(request);
    ro?.observe(node);
    measure();
    return () => {
      cancelAnimationFrame(frame);
      target.removeEventListener("scroll", request);
      window.removeEventListener("resize", request);
      ro?.disconnect();
    };
  }, [ref, scrollContainer]);
  return progress;
}
export function useSphereRotation(
  active: boolean,
  reduced: boolean,
  autoplay: boolean,
  speed: number,
  drag: boolean,
) {
  const state = useRef({
      yaw: 0,
      pitch: 0,
      vx: 0,
      vy: 0,
      target: null as null | { yaw: number; pitch: number },
    }),
    [rotation, setRotation] = useState({ yaw: 0, pitch: 0 }),
    pointer = useRef<null | { id: number; x: number; y: number; time: number }>(
      null,
    );
  const publish = () =>
    setRotation({ yaw: state.current.yaw, pitch: state.current.pitch });
  useSectionLoop(active && !reduced, (delta) => {
    const s = state.current;
    if (pointer.current) return;
    if (s.target) {
      const ease = 1 - Math.exp(-delta * 6);
      s.yaw += (s.target.yaw - s.yaw) * ease;
      s.pitch += (s.target.pitch - s.pitch) * ease;
      if (
        Math.abs(s.yaw - s.target.yaw) + Math.abs(s.pitch - s.target.pitch) <
        0.001
      )
        s.target = null;
    } else {
      s.yaw += (s.vx + (autoplay ? speed : 0)) * delta;
      s.pitch = sectionClamp(s.pitch + s.vy * delta, -1.2, 1.2);
      s.vx *= Math.exp(-delta * 5);
      s.vy *= Math.exp(-delta * 5);
    }
    publish();
  });
  const orient = useCallback(
    (yaw: number, pitch: number) => {
      const s = state.current;
      const shortest =
        ((((yaw - s.yaw + Math.PI) % (Math.PI * 2)) + Math.PI * 2) %
          (Math.PI * 2)) -
        Math.PI;
      s.vx = 0;
      s.vy = 0;
      if (reduced) {
        s.yaw += shortest;
        s.pitch = pitch;
        s.target = null;
        setRotation({ yaw: s.yaw, pitch: s.pitch });
      } else s.target = { yaw: s.yaw + shortest, pitch };
    },
    [reduced],
  );
  const end = (event: PointerEvent<HTMLElement>) => {
    if (pointer.current?.id !== event.pointerId) return;
    pointer.current = null;
    if (reduced) {
      state.current.vx = 0;
      state.current.vy = 0;
    }
    event.currentTarget.releasePointerCapture?.(event.pointerId);
  };
  return {
    rotation,
    orient,
    handlers: {
      onPointerDown: (event: PointerEvent<HTMLElement>) => {
        if (
          !drag ||
          event.button !== 0 ||
          (event.target as HTMLElement).closest("button,a,input")
        )
          return;
        pointer.current = {
          id: event.pointerId,
          x: event.clientX,
          y: event.clientY,
          time: event.timeStamp,
        };
        state.current.target = null;
        state.current.vx = state.current.vy = 0;
        event.currentTarget.setPointerCapture?.(event.pointerId);
      },
      onPointerMove: (event: PointerEvent<HTMLElement>) => {
        const p = pointer.current;
        if (!p || p.id !== event.pointerId) return;
        const dx = (event.clientX - p.x) * 0.006,
          dy = (event.clientY - p.y) * 0.006,
          dt = Math.max(0.008, (event.timeStamp - p.time) / 1000);
        state.current.yaw += dx;
        state.current.pitch = sectionClamp(state.current.pitch + dy, -1.2, 1.2);
        state.current.vx = sectionClamp(dx / dt, -5, 5);
        state.current.vy = sectionClamp(dy / dt, -3, 3);
        pointer.current = {
          id: p.id,
          x: event.clientX,
          y: event.clientY,
          time: event.timeStamp,
        };
        publish();
      },
      onPointerUp: end,
      onPointerCancel: end,
      onLostPointerCapture: () => {
        pointer.current = null;
      },
    },
  };
}
export function SectionImage({
  item,
  className,
  style,
}: {
  item: SectionInternalMedia;
  className?: string;
  style?: CSSProperties;
}) {
  return item.content ? (
    <div className={className} style={style}>
      {item.content}
    </div>
  ) : item.src ? (
    <img
      className={className}
      style={style}
      src={item.src}
      alt={item.alt ?? ""}
      draggable={false}
    />
  ) : (
    <div className={className} style={style} />
